mapper.select:
SELECT TO_CHAR(O.PAY_DATE, 'YYYYMMDD') AS OPERATE_DATE, TO_CHAR(O.PAY_DATE, 'YYYYMMDDHH24MISS') AS TXN_DATE_TIME, O.PAY_DATE AS PAY_DATE, O.ORDER_NO AS ORDER_NO, O.PAY_AMOUNT AS PAY_AMOUNT, I.CARD_NUM AS CARD_NUM FROM DAILY_TICKET_ORDER O LEFT JOIN DAILY_TICKET_INSTANCE I ON I.ORDER_NO = O.ORDER_NO WHERE O.PAY_STATUS = 'PAID' AND O.PAY_DATE >= #{windowStart,jdbcType=TIMESTAMP} AND O.PAY_DATE < #{windowEnd,jdbcType=TIMESTAMP}
AND (O.PAY_DATE > #{lastPayDate,jdbcType=TIMESTAMP} OR (O.PAY_DATE = #{lastPayDate,jdbcType=TIMESTAMP} AND O.ORDER_NO > #{lastOrderNo,jdbcType=VARCHAR}))
ORDER BY O.PAY_DATE, O.ORDER_NO FETCH FIRST #{limit} ROWS ONLY
